// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract A { uint8 public immutable base = 2; } contract C is A { uint8 public immutable derived; constructor(uint8 input) { derived = base + input; } function combined() external view returns (uint8) { return base + derived; } }
